def run(context):
    app = adsk.core.Application.get()
    ui = app.userInterface
    try:
        doc = app.documents.add(adsk.core.DocumentTypes.FusionDesignDocumentType)
        design = adsk.fusion.Design.cast(app.activeProduct)
        design.designType = adsk.fusion.DesignTypes.ParametricDesignType
        root = design.rootComponent
        root.name = 'BMW_E30_WallArt'

        design.userParameters.add('PanelThickness',
            adsk.core.ValueInput.createByReal(PANEL_THICKNESS_MM / 10.0), 'cm',
            'Panel thickness')

        k = (PANEL_WIDTH_MM / BASE_WIDTH_MM) / 10.0     # mm -> cm, with width scaling
        sketch = root.sketches.add(root.xYConstructionPlane)
        sketch.name = 'E30 outline'
        sketch.isComputeDeferred = True                 # much faster for thousands of lines
        lines = sketch.sketchCurves.sketchLines
        P = adsk.core.Point3D.create
        for flat in RINGS:
            n = len(flat) // 2
            pts = [P(flat[2*i] * k, flat[2*i+1] * k, 0) for i in range(n)]
            prev = None; first = None
            for i in range(n):
                a = pts[i]; b = pts[(i + 1) % n]
                if prev is None:
                    ln = lines.addByTwoPoints(a, b); first = ln
                elif i == n - 1:
                    ln = lines.addByTwoPoints(prev.endSketchPoint, first.startSketchPoint)
                else:
                    ln = lines.addByTwoPoints(prev.endSketchPoint, b)
                prev = ln
        sketch.isComputeDeferred = False

        # The panel is the largest profile (outer silhouette with all white areas cut out);
        # the small white-area profiles are not extruded.
        best = max(sketch.profiles, key=lambda p: p.areaProperties().area)
        sel = adsk.core.ObjectCollection.create(); sel.add(best)

        ext = root.features.extrudeFeatures
        inp = ext.createInput(sel, adsk.fusion.FeatureOperations.NewBodyFeatureOperation)
        inp.setDistanceExtent(False, adsk.core.ValueInput.createByString('PanelThickness'))
        feat = ext.add(inp)
        feat.bodies.item(0).name = 'E30_Panel'
        app.activeViewport.fit()
        ui.messageBox('Done: 1 solid body, %d sketch loops.' % len(RINGS))
    except:
        if ui:
            ui.messageBox('Failed:\n%s' % traceback.format_exc())
